system.GetVisualSystem().SetRenderMode(pychrono.ChVisualSystemIrrlicht.eRENDER_CONTACT_INTERNAL_FORCES_AND_NORMALS_AND_CONTACT_FORCES_AND_CONTACT_NORMALS)
